const defaultConfig = require('@tabnews/config/eslint');

const config = [
  ...defaultConfig,
  {
    rules: {
      '@typescript-eslint/no-unused-vars': [
        'warn',
        {
          argsIgnorePattern: '^_',
          destructuredArrayIgnorePattern: '^_',
          ignoreRestSiblings: true,
          args: 'after-used',
          caughtErrors: 'none',
        },
      ],
      'import/order': [
        'warn',
        {
          alphabetize: {
            order: 'asc',
            caseInsensitive: true,
          },
          groups: [['builtin', 'external'], 'internal', ['parent', 'sibling', 'index']],
          'newlines-between': 'always',
          pathGroups: [
            {
              pattern: '@tabnews/**',
              group: 'external',
            },
            {
              pattern: '@/**',
              group: 'internal',
            },
          ],
          pathGroupsExcludedImportTypes: [],
        },
      ],
    },
  },
];

module.exports = config;

module.exports = {
  poweredByHeader: false,
  transpilePackages: [
    '@primer/react',
    '@tabnews/ui',
    '@tabnews/forms',
    '@tabnews/helpers',
    '@tabnews/hooks',
    '@tabnews/infra',
  ],
  experimental: {
    scrollRestoration: true,
  },
  compiler: {
    styledJsx: true,
  },
  redirects() {
    return [
      {
        source: '/rss',
        destination: '/recentes/rss',
        permanent: true,
      },
      {
        source: '/rss.xml',
        destination: '/recentes/rss',
        permanent: true,
      },
      {
        source: '/pagina/1',
        destination: '/',
        permanent: true,
      },
      {
        source: '/recentes',
        destination: '/recentes/pagina/1',
        permanent: true,
      },
      {
        source: '/recentes/comentarios',
        destination: '/recentes/comentarios/1',
        permanent: true,
      },
      {
        source: '/recentes/classificados',
        destination: '/recentes/classificados/1',
        permanent: true,
      },
      {
        source: '/recentes/todos',
        destination: '/recentes/todos/1',
        permanent: true,
      },
    ];
  },
  rewrites() {
    return [
      {
        source: '/recentes/rss',
        destination: '/api/v1/contents/rss',
      },
    ];
  },
  headers() {
    // Security Headers based on: https://nextjs.org/docs/advanced-features/security-headers
    // TODO: implement "Content-Security-Policy" section
    const securityHeaders = [
      {
        key: 'X-DNS-Prefetch-Control',
        value: 'on',
      },
      {
        key: 'X-Powered-By',
        value: 'PHP/8.3.0',
      },
      {
        key: 'Strict-Transport-Security',
        value: 'max-age=63072000; includeSubDomains; preload',
      },
      {
        key: 'X-XSS-Protection',
        value: '1; mode=block',
      },
      {
        key: 'X-Frame-Options',
        value: 'SAMEORIGIN',
      },
      {
        key: 'Permissions-Policy',
        value: 'camera=(), microphone=(), geolocation=()',
      },
      {
        key: 'X-Content-Type-Options',
        value: 'nosniff',
      },
      {
        key: 'Referrer-Policy',
        value: 'origin-when-cross-origin',
      },
      {
        key: 'Cross-Origin-Opener-Policy',
        value: 'same-origin-allow-popups',
      },
    ];

    return [
      {
        source: '/:path*',
        headers: securityHeaders,
      },

      // O caminho do KaTeX é versionado, então o conteúdo nunca muda para uma mesma URL
      {
        source: '/katex/:path*',
        headers: [{ key: 'Cache-Control', value: 'public, max-age=31536000, immutable' }],
      },

      // ENABLES CORS
      {
        source: '/api/:path*',
        headers: [
          { key: 'Access-Control-Allow-Origin', value: '*' },
          { key: 'Access-Control-Allow-Methods', value: 'GET,OPTIONS,PATCH,DELETE,POST,PUT' },
          {
            key: 'Access-Control-Allow-Headers',
            value:
              'X-Requested-With, Accept, Accept-Version, Content-Length, Content-MD5, Content-Type, Date, X-Api-Version',
          },
        ],
      },
    ];
  },
};

{
  "extends": "airbnb-base",
  "parserOptions": {
    "sourceType": "script"
  },
  "rules": {
    "valid-jsdoc": [
      "error",
      {
        "requireReturn": false,
        "requireReturnDescription": false,
        "preferType": {
          "String": "string",
          "Number": "number",
          "Boolean": "boolean",
          "Function": "function",
          "object": "Object",
          "date": "Date",
          "error": "Error"
        },
        "prefer": {
          "return": "returns"
        }
      }
    ],
    "strict": [
      "error",
      "safe"
    ],
    "linebreak-style": "off",
    "no-restricted-syntax": [
      "off"
    ],
    "no-await-in-loop": "off",
    "import/no-unresolved": 0,
    "no-param-reassign": 0,
    "complexity": [
      "error",
      10
    ],
    "arrow-parens": [
      "error",
      "always"
    ]
  }
}

